// Included within Window. The shared undo stack stores conceptual and logical edits.
 void updateLevelStatus(){
  if(!levelStatus)return;
  QString text=model.logical.isEmpty()?t("Logico non generato","Logical model not generated"):logicalStale(model)?t("Logico da aggiornare","Logical model out of date"):t("Logico aggiornato","Logical model up to date");levelStatus->setText(text);levelStatus->setToolTip(t("Le modifiche concettuali non sovrascrivono il logico. Usa Genera / Aggiorna logico per rivedere la traduzione.","Conceptual edits never overwrite the logical model. Use Generate / Update logical model to review the mapping."));if(generateAction)generateAction->setText(model.logical.isEmpty()?t("Genera logico…","Generate logical…"):t("Aggiorna logico…","Update logical…"));
 }
 void levelControls(QToolBar *display,QMenu *tools){
  generateAction=action(tools,model.logical.isEmpty()?t("Genera logico…","Generate logical…"):t("Aggiorna logico…","Update logical…"),{},[this]{if(generateDialog())switchLevel(true);});generateAction->setObjectName("generateLogical");display->addAction(generateAction);
  auto report=action(tools,t("Dal concettuale alle tabelle…","From concepts to tables…"),{},[this]{logicalReport();});report->setEnabled(!model.logical.isEmpty());report->setObjectName("logicalReport");
  levelStatus=new QLabel;statusBar()->addPermanentWidget(levelStatus);updateLevelStatus();
 }
 void switchLevel(bool value){
  if(value&&model.logical.isEmpty()&&!generateDialog()){if(levelBox){QSignalBlocker block(levelBox);levelBox->setCurrentIndex(logicalView?1:0);}return;}
  logicalView=value;selection.clear();selectionIds.clear();buildMenus();refresh();fit();
 }
 QString schemaDetails(const LogicalSchema &schema)const{
  QString html="<h3>"+t("Traduzione concettuale → logico","Conceptual → logical mapping")+"</h3><p>"+QString::number(schema.tables.size())+t(" tabelle. Strategia ISA: superclasse + sottoclassi."," tables. ISA strategy: superclass + subclass tables.")+"</p>";
  html+="<p>"+t("PK = chiave primaria; FK = chiave esterna; UNIQUE = unicità dell’intero gruppo di colonne. I tipi SQL appartengono al successivo livello fisico.","PK = primary key; FK = foreign key; UNIQUE = uniqueness of the entire column group. SQL types belong to the subsequent physical level.")+"</p>";
  for(const auto &table:schema.tables){QStringList cols;for(const auto &c:table.columns)cols<<c.name+(c.dataType.isEmpty()?QString():": "+genericTypeName(c.dataType,en))+(c.typeOverride?t(" (personalizzato)"," (overridden)"):QString())+(c.pk?" [PK]":"");html+="<p><b>"+table.name.toHtmlEscaped()+"</b>: "+cols.join(", ").toHtmlEscaped()+"</p>";}
  html+="<h3>"+t("Regole applicate e vincoli residui","Applied rules and remaining constraints")+"</h3><ul>";for(const auto &message:schema.messages)html+="<li>"+(message.warning?"<b>"+t("Da verificare: ","To verify: ")+"</b>":QString())+(en?message.en:message.it).toHtmlEscaped()+"</li>";return html+"</ul>";
 }
 bool generateDialog(){
  QDialog dialog(this);dialog.setObjectName("mappingDialog");dialog.setWindowTitle(t("Genera / aggiorna modello logico","Generate / update logical model"));QVBoxLayout layout(&dialog);auto intro=new QLabel(t("Controlla le tabelle che verranno create. Il disegno concettuale resta invariato. Se compaiono delle scelte, decidi dove conservare il collegamento.","Review the tables to be created. The conceptual diagram stays unchanged. If choices appear, decide where to store the link."));intro->setWordWrap(true);layout.addWidget(intro);
  auto choicesArea=new QWidget;auto form=new QFormLayout(choicesArea);auto choiceScroll=new QScrollArea;choiceScroll->setWidgetResizable(true);choiceScroll->setMaximumHeight(180);choiceScroll->setWidget(choicesArea);layout.addWidget(choiceScroll);QMap<QString,QComboBox*> combos;LogicalSchema previous;QString parseError;if(!model.logical.isEmpty())LogicalSchema::parse(model.logical,previous,parseError);
  for(const auto&r:model.objects)if(r.kind=="relation"&&!r.identifying&&r.cardA.endsWith("1")&&r.cardB.endsWith("1")){auto a=model.get(r.a),b=model.get(r.b);auto combo=new QComboBox;combo->addItem(t("FK in A: ","FK in A: ")+a->name,"A");combo->addItem(t("FK in B: ","FK in B: ")+b->name,"B");auto side=previous.oneToOne.value(r.id,r.cardA.startsWith("1")&&!r.cardB.startsWith("1")?"A":"B");combo->setCurrentIndex(side=="A"?0:1);form->addRow(r.name,combo);combos[r.id]=combo;}
  choiceScroll->setVisible(!combos.isEmpty());
  QCheckBox preserve(t("Conserva nomi, tipi personalizzati, nullabilità e posizioni degli elementi ancora presenti","Keep custom names, type overrides, nullability and positions of surviving elements"));preserve.setChecked(true);preserve.setVisible(!model.logical.isEmpty());layout.addWidget(&preserve);QTextBrowser browser;browser.setObjectName("mappingSummary");layout.addWidget(&browser,1);QCheckBox details(t("Mostra dettagli","Show details"));details.setObjectName("showMappingDetails");layout.addWidget(&details);QDialogButtonBox buttons(QDialogButtonBox::Cancel);auto applyMapping=buttons.addButton(t("Applica traduzione","Apply mapping"),QDialogButtonBox::AcceptRole);applyMapping->setObjectName("applyMapping");layout.addWidget(&buttons);LogicalSchema candidate;
  QStringList previewErrors;
  auto render=[&]{
   if(!previewErrors.isEmpty()){browser.setHtml(learningCard(t("Correggi prima questi problemi","Resolve these issues first"),"<p>"+previewErrors.join("\n").toHtmlEscaped().replace("\n","<br>")+"</p>",3));return;}
   QString diff;
   if(!model.logical.isEmpty()){auto changes=logicalDifferences(previous,candidate);int removed=0;for(const auto &change:changes)removed+=change.action=="removed";
    if(!changes.isEmpty())diff=learningCard(t("Cosa cambierà","What will change"),"<p>"+QString::number(changes.size())+t(" elementi modificati; rimossi: "," elements changed; removed: ")+QString::number(removed)+". "+t("Apri i dettagli prima di applicare per vedere quali.","Open details before applying to see which ones.")+"</p>",removed?2:1);
   }
   browser.setHtml(diff+schemaReport(candidate)+(details.isChecked()?learningCard(t("Dettagli della trasformazione","Mapping details"),(!model.logical.isEmpty()?mappingChanges(previous,candidate):QString())+schemaDetails(candidate),1):QString()));
  };
  auto preview=[&]{QMap<QString,QString> choices;for(auto i=combos.begin();i!=combos.end();++i)choices[i.key()]=i.value()->currentData().toString();previewErrors.clear();candidate=generateLogical(model,choices,previewErrors,en);if(previewErrors.isEmpty()&&preserve.isChecked()&&!model.logical.isEmpty()){preserveLogicalEdits(candidate,previous);previewErrors=candidate.issues(en);}applyMapping->setEnabled(previewErrors.isEmpty());render();};
  connect(&details,&QCheckBox::toggled,&dialog,[&]{render();});

  for(auto combo:combos){connect(combo,QOverload<int>::of(&QComboBox::currentIndexChanged),&dialog,[&]{preview();});}
  connect(&preserve,&QCheckBox::toggled,&dialog,[&]{preview();});connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);preview();dialog.resize(860,700);if(dialog.exec()!=QDialog::Accepted)return false;
  auto data=candidate.json();if(!change(t("Traduci modello logico","Map logical model"),[=](Model &m){m.logical=data;}))return false;buildMenus();refresh();return true;
 }
 void logicalReport(){if(model.logical.isEmpty())return;QScopedPointer<QDialog> dialog(mappingExplanationDialog());dialog->exec();}

 QString columnFlags(const LogicalTable &table,const LogicalColumn &c)const{QStringList tags;if(c.pk)tags<<"PK";for(const auto&fk:table.foreignKeys)if(fk.columns.contains(c.id)){tags<<"FK";break;}for(const auto&u:table.uniqueKeys)if(u.size()==1&&u.contains(c.id)){tags<<"UQ";break;}if(!c.nullable)tags<<"NN";return tags.join(" · ");}
 QString columnLabel(const LogicalTable &table,const LogicalColumn &c)const{auto flags=columnFlags(table,c);return c.name+(showTypes&&!c.dataType.isEmpty()?": "+genericTypeName(c.dataType,en):QString())+(flags.isEmpty()?QString():"  ["+flags+"]");}
 void refreshLogical(){
  QString error;LogicalSchema::parse(model.logical,logicalCache,error);rebuilding=true;roleBadges.clear();nodes.clear();connectors.clear();scene->clear();tree->clear();QFont font("Segoe UI");font.setPixelSize(14);QFontMetricsF fm(font);
  for(const auto&t:logicalCache.tables){auto item=new QTreeWidgetItem(tree);item->setText(0,t.name);item->setData(0,Qt::UserRole,t.id);auto node=new Node;node->id=t.id;node->setData(0,t.id);node->kind="entity";node->uml=true;node->label=t.name;node->theme=theme;double width=qMax(230.,fm.horizontalAdvance(t.name)+48);for(const auto&c:t.columns)width=qMax(width,fm.horizontalAdvance(columnLabel(t,c))+48);node->size={width,qMax(80.,48.+t.columns.size()*30.)};scene->addItem(node);node->setPos(t.position);nodes[t.id]=node;node->setToolTip(richTip(t.name+"\n"+this->t("Tabella logica derivata. Trascina l’intestazione per spostarla. F2 rinomina. Il menu destro mostra l’origine concettuale.","Derived logical table. Drag its header to move it. F2 renames it. The context menu shows its conceptual source.")));
   int index=0;for(const auto&c:t.columns){auto child=new QTreeWidgetItem(item);child->setText(0,columnLabel(t,c));child->setData(0,Qt::UserRole,c.id);auto row=new Node;row->id=c.id;row->setData(0,c.id);row->kind="attribute";row->uml=true;row->key=c.pk;row->theme=theme;row->label=child->text(0);row->size={width-16,28};row->setParentItem(node);row->setFlag(QGraphicsItem::ItemIsMovable,false);row->setPos(0,-node->size.height()/2+57+index++*30);row->setToolTip(richTip(row->label+"\n"+this->t("PK: chiave primaria; FK: chiave esterna; UQ: unicità della colonna; NN: valore obbligatorio. I vincoli composti sono elencati nelle proprietà della tabella.","PK: primary key; FK: foreign key; UQ: single-column uniqueness; NN: required value. Composite constraints are listed in table properties.")));nodes[c.id]=row;}
  }
  renderNotes();logicalLinks();scene->setSceneRect(-200000,-200000,400000,400000);normalizeSelection();for(auto id:selectionIds)if(nodes.contains(id))nodes[id]->setSelected(true);tree->expandAll();rebuilding=false;syncTree();inspector();updateStatus();title();updateLevelStatus();
 }
 void logicalLinks(){
  for(auto item:connectors){delete item;}
  connectors.clear();
  for(const auto&t:logicalCache.tables)for(const auto&fk:t.foreignKeys){auto source=nodes.value(t.id),target=nodes.value(fk.target);if(!source||!target)continue;QPointF a,b;QPainterPath path;QStringList columns;for(auto id:fk.columns)columns<<t.column(id)->name;
   if(source==target){a=source->pos()+QPointF(source->size.width()/2,-10);b=a+QPointF(0,30);path.moveTo(a);path.lineTo(a+QPointF(70,0));path.lineTo(b+QPointF(70,0));path.lineTo(b);}else{a=boundary(source,target->pos());b=boundary(target,source->pos());path.moveTo(a);path.lineTo(b);}
   auto line=new LinkItem(path);line->setPen(QPen(theme.line,1.6));line->setData(0,t.id);line->setZValue(-2);line->setToolTip(richTip("FK: "+t.name+" ("+columns.join(", ")+") → "+logicalCache.table(fk.target)->name));scene->addItem(line);connectors<<line;
   QLineF direction(source==target?b+QPointF(70,0):a,b);double angle=std::atan2(direction.dy(),direction.dx());QPointF back=b-QPointF(std::cos(angle)*13,std::sin(angle)*13),perp(-std::sin(angle)*6,std::cos(angle)*6);QPolygonF triangle;triangle<<b<<back+perp<<back-perp;auto arrow=scene->addPolygon(triangle,QPen(theme.line),theme.line);arrow->setZValue(-1);arrow->setData(0,t.id);connectors<<arrow;currentLinkId=t.id;linkText("FK",path.pointAtPercent(.5)+QPointF(0,-14));
  }
 }
 void moveLogicalDrag(QPointF delta){model=dragBefore;moveNotesDrag(delta);LogicalSchema schema;QString error;if(!LogicalSchema::parse(dragBefore.logical,schema,error))return;for(auto&t:schema.tables)if(dragIds.contains(t.id))t.position+=delta;logicalCache=schema;model.logical=schema.json();rebuilding=true;for(const auto&t:schema.tables)if(nodes.contains(t.id))nodes[t.id]->setPos(t.position);logicalLinks();rebuilding=false;}
 void alignLogical(bool horizontal){arrangeSelection(horizontal?0:1);}

 void showOrigin(){auto table=logicalCache.owner(selection);if(!table)return;auto column=table->column(selection);QString source=column?columnOrigin(logicalCache,column->id).attribute:table->source;if(!model.get(source)){QMessageBox::information(this,t("Origine","Source"),t("L’elemento concettuale non è più presente. Aggiorna il modello logico.","The conceptual element no longer exists. Update the logical model."));return;}switchLevel(false);selectOnly(source);fitSelection();}
 void applyLogicalProperties(QString id,QString name,bool nullable,QString typeChoice=QString()){auto schema=logicalCache;auto table=schema.owner(id);if(!table)return;auto column=table->column(id);if(column){column->name=name.trimmed();if(!column->generated&&!typeChoice.isNull()){column->typeOverride=typeChoice!="__inherit";column->dataType=column->typeOverride?typeChoice:column->autoDataType;}if(!column->pk&&!column->generated)column->nullable=nullable;}else table->name=name.trimmed();synchronizeForeignKeyTypes(schema);auto errors=schema.issues(en);if(!errors.isEmpty()){QMessageBox::warning(this,t("Modello logico","Logical model"),errors.join("\n"));return;}change(t("Modifica proprietà logiche","Edit logical properties"),[=](Model &m){m.logical=schema.json();});}
 void renameLogical(QString id){auto table=logicalCache.owner(id);if(!table)return;auto c=table->column(id);bool ok=false;auto name=QInputDialog::getText(this,t("Rinomina nel logico","Rename in logical model"),t("Nome","Name"),QLineEdit::Normal,c?c->name:table->name,&ok).left(200);if(ok)applyLogicalProperties(id,name,c?c->nullable:false);}
 void logicalInspector(){
  if(selectionIds.size()>1){note(t("SELEZIONE MULTIPLA · LOGICO","MULTIPLE SELECTION · LOGICAL"));note(t("Trascina le intestazioni delle tabelle per spostare il gruppo. I nomi logici non modificano il concettuale.","Drag table headers to move the group. Logical names do not change the conceptual model."));return;}
  auto table=logicalCache.owner(selection);if(!table){note(t("MODELLO LOGICO","LOGICAL MODEL"));note(t("Seleziona una tabella o una colonna. PK = chiave primaria, FK = chiave esterna, NN = obbligatorio. Mostra origine torna all’elemento concettuale. Usa Aggiorna logico dopo modifiche al concettuale.","Select a table or column. PK = primary key, FK = foreign key, NN = required. Show source returns to its conceptual element. Use Update logical after conceptual edits."));if(logicalStale(model))note(t("ATTENZIONE: il concettuale è cambiato; questo logico è da aggiornare.","NOTICE: the conceptual model has changed; this logical model needs updating."));return;}
  auto c=table->column(selection);note(c?t("COLONNA LOGICA","LOGICAL COLUMN"):t("TABELLA LOGICA","LOGICAL TABLE"));const quint64 epoch=documentEpoch;QString id=selection;auto name=field(t("Nome","Name"),c?c->name:table->name);auto original=model.get(c?c->source:table->source);note(t("Origine: ","Source: ")+(original?original->name:t("rimossa dal concettuale","removed from conceptual model")));QCheckBox *nullable=nullptr;QComboBox *dataType=nullptr;
  if(c){dataType=typeCombo(c->dataType);if(!c->generated){dataType->insertItem(0,t("Ereditato: ","Inherited: ")+genericTypeName(c->autoDataType,en),"__inherit");dataType->setCurrentIndex(c->typeOverride?dataType->findData(c->dataType):0);}else dataType->setEnabled(false);form->addRow(t("Tipo di dato","Data type"),dataType);
   note(c->generated?t("Tipo ereditato dalla chiave referenziata. Modificalo sulla colonna di origine; tutte le FK collegate si aggiornano insieme.","Type inherited from the referenced key. Edit the source column; all linked FKs update together."):c->typeOverride?t("Tipo personalizzato nel logico. Il concettuale rimane invariato; scegli Ereditato per rimuovere la personalizzazione.","Type customized in the logical model. The conceptual model stays unchanged; choose Inherited to remove the override."):t("Tipo ereditato dal concettuale alla generazione. Puoi personalizzarlo qui oppure aggiornare il concettuale e rigenerare.","Type inherited from the conceptual model when generated. You may override it here or edit the conceptual model and regenerate."));note(columnFlags(*table,*c));nullable=new QCheckBox(t("Ammette valori nulli","Allows null values"));nullable->setChecked(c->nullable);nullable->setEnabled(!c->pk&&!c->generated);form->addRow(nullable);note(c->generated?t("Colonna generata da una relazione o ISA: chiave e nullabilità derivano dalle regole di traduzione.","Column generated by a relationship or ISA: key and nullability follow mapping rules."):t("Il nome logico può essere personalizzato senza rinominare l’attributo concettuale.","The logical name can be customized without renaming the conceptual attribute."));}
  else{QStringList keys;for(auto id:table->primaryKey())keys<<table->column(id)->name;note("PK: "+keys.join(" + "));for(const auto&fk:table->foreignKeys){QStringList cols;for(auto id:fk.columns)cols<<table->column(id)->name;note("FK ("+cols.join(", ")+") → "+logicalCache.table(fk.target)->name);}for(const auto&u:table->uniqueKeys){QStringList cols;for(auto id:u)cols<<table->column(id)->name;note("UNIQUE ("+cols.join(", ")+")");}}
  note(t("Tipi SQL e generazione codice sono disponibili nel livello Fisico/SQL (F8).","SQL types and code generation are available in the Physical/SQL level (F8)."));auto apply=new QPushButton(t("Applica modifiche","Apply changes"));apply->setObjectName("applyLogicalProperties");form->addRow(apply);connect(apply,&QPushButton::clicked,this,[=]{QString value=name->text();QString typeChoice=dataType?dataType->currentData().toString():QString();bool nulls=nullable&&nullable->isChecked();QTimer::singleShot(0,this,[=]{if(epoch==documentEpoch)applyLogicalProperties(id,value,nulls,typeChoice);});});auto origin=new QPushButton(t("Mostra origine concettuale","Show conceptual source"));form->addRow(origin);connect(origin,&QPushButton::clicked,this,[this]{showOrigin();});if(c){originInspector(c->id);const auto trace=columnOrigin(logicalCache,c->id);if(!trace.relations.isEmpty()&&model.get(trace.relations.first())){auto relation=new QPushButton(t("Mostra associazione / ISA","Show relationship / ISA"));form->addRow(relation);connect(relation,&QPushButton::clicked,this,[this,target=trace.relations.first()]{switchLevel(false);selectOnly(target);fitSelection();});}}
 }
 QMenu *logicalContextMenu(QString hit){Q_UNUSED(hit);auto menu=new QMenu(this);if(!selectionIds.isEmpty()){if(selectionIds.size()==1){action(menu,t("Proprietà…","Properties…"),{},[this]{showProperties();});action(menu,t("Rinomina nel logico…","Rename in logical…"),{},[this]{renameLogical(selection);});action(menu,t("Mostra origine concettuale","Show conceptual source"),{},[this]{showOrigin();});}action(menu,t("Inquadra selezione","Fit selection"),{},[this]{fitSelection();});menu->addSeparator();}auto arrange=menu->addMenu(t("Disponi","Arrange"));addArrangementActions(arrange);action(menu,t("Dal concettuale alle tabelle…","From concepts to tables…"),{},[this]{logicalReport();});action(menu,t("Aggiorna logico…","Update logical…"),{},[this]{generateDialog();});action(menu,t("Adatta diagramma","Fit diagram"),{},[this]{fit();});return menu;}
